'use strict';
const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const b=require('./chief-factory-dispatch-v01.cjs');
const source=JSON.parse(fs.readFileSync(path.join(__dirname,'../contracts/chief-factory-dispatch-v01.json')));
const clone=x=>structuredClone(x),NOW=Date.parse('2026-10-07T16:00:00Z');
function fixture(){
  const m=clone(source);m.consumer_enabled=true;
  const c=m.contracts[0];c.authorization={ref:'shannon-activation:offline-fixture-only',approved_by:'Shannon',approved_at:'2026-10-07T15:00:00Z',expires_at:'2026-10-08T15:00:00Z',contract_digest:b.contractDigest(c)};
  const r=b.proposedRequest(m,'2026-10-07T15:30:00Z');
  const db={rows:[],writes:0,failBefore:null,failAfter:null,
    async list(){return clone(this.rows);},async read(id){const row=this.rows.find(r=>r.id===id);if(!row)throw Error('NOT_FOUND');return clone(row);},
    async create(fields){const row={id:'rec'+String(this.rows.length+1).padStart(14,'0'),fields:clone(fields)};this.rows.push(row);this.writes++;return clone(row);},
    async patch(id,fields){if(this.failBefore?.(fields)){this.failBefore=null;throw Error('INJECTED_BEFORE_WRITE');}Object.assign(this.rows.find(r=>r.id===id).fields,clone(fields));this.writes++;if(this.failAfter?.(fields)){this.failAfter=null;throw Error('INJECTED_AFTER_WRITE');}return this.read(id);}
  };
  const gh={preflights:0,workers:0,verifications:0,artifactValid:true,successful:true,
    async preflight(){this.preflights++;},async checkpoint(c){this.workers++;return b.evidence(c,c.target.source_commit,c.target.source_blobs);},
    async verifyArtifact(receipt,success){this.verifications++;if(!this.artifactValid)throw Error('ARTIFACT_PROVENANCE');if(success&&!this.successful)throw Error('RUN_NOT_SUCCESSFUL');}
  };
  return {m,c,r,db,gh};
}
const artifact={run_id:'12345',artifact_id:'67890',artifact_digest:'a'.repeat(64)};
async function built(f){const s=await b.submit(f.m,f.r,f.db,NOW);const result=await b.consume(f.m,f.db,f.gh,NOW,'12345');return {...s,...result};}
async function done(f){const s=await built(f);await b.complete(f.m,s.record,artifact,f.db,f.gh,NOW);return s;}
const reject=(fn,code)=>assert.rejects(fn,new RegExp(code));
test('checked-in activation and authorization gates are closed',()=>{assert.equal(source.consumer_enabled,false);assert.equal(source.contracts[0].authorization,null);assert.ok(b.validateManifest(source));});
test('disabled consumer never reads mailbox or obtains credentials',async()=>{assert.deepEqual(await b.consume(source,{list(){throw Error('LIVE_READ');}},null,NOW,'1'),{decision:'DISABLED'});});
test('disabled submission never writes',async()=>{const f=fixture();f.m.consumer_enabled=false;await reject(()=>b.submit(f.m,f.r,f.db,NOW),'ACTIVATION_REQUIRED');assert.equal(f.db.writes,0);});
test('positive staged → READY → CLAIMED → checkpoint → COMPLETE → independent retrieval',async()=>{const f=fixture(),s=await done(f);assert.equal(b.get(f.m,await f.db.read(s.record),'status'),'COMPLETE');const verified=await b.retrieve(f.m,s.record,f.r,f.db,f.gh,NOW);assert.equal(verified.status,'VERIFIED_COMPLETE');assert.equal(verified.receipt.identity.attempt_id,'AIR-BRIDGE-001-DISPATCH-1');assert.equal(f.gh.workers,2);assert.equal(f.gh.verifications,2);});
test('staging status is never executable',async()=>{const f=fixture();await f.db.create(b.fields(f.m,{id:f.r.work_order_id,task:f.r.task_class,status:'AWAITING_APPROVAL',payload:b.canonical(f.r)}));assert.deepEqual(await b.consume(f.m,f.db,f.gh,NOW,'12345'),{decision:'IDLE'});assert.equal(f.gh.workers,0);});
for(const [name,mutate,code] of [
 ['unsupported task',f=>f.r.task_class='arbitrary-agent','UNSUPPORTED'],
 ['unknown contract',f=>f.r.contract_id='new-handler','UNSUPPORTED'],
 ['mutated payload digest',f=>f.r.contract_digest='f'.repeat(64),'UNSUPPORTED'],
 ['wrong correlation',f=>f.r.correlation_id='foreign','UNSUPPORTED'],
 ['missing approval',f=>f.c.authorization=null,'MISSING'],
 ['foreign approval ref',f=>f.r.authorization_ref='shannon-activation:other','MISSING'],
 ['stale approval',f=>{f.c.authorization.expires_at='2026-10-07T15:45:00Z';},'STALE'],
 ['future request',f=>f.r.created_at='2026-10-07T16:01:00Z','REQUEST_TIME'],
 ['request precedes approval',f=>f.r.created_at='2026-10-07T14:59:00Z','REQUEST_TIME'],
 ['wrong repository',f=>f.c.target.repository='VeritasDesign/other','TARGET'],
 ['wrong branch',f=>f.c.target.base_branch='production','TARGET'],
 ['wrong source',f=>f.c.target.source_commit='f'.repeat(40),'SOURCE_CONTRACT'],
 ['wrong blob',f=>{f.c.target.source_blobs[Object.keys(f.c.target.source_blobs)[0]]='f'.repeat(40);},'SOURCE_CONTRACT'],
 ['shell request',f=>f.r.command='$(touch /tmp/should-not-exist)','REQUEST_SHAPE'],
 ['repository supplied by request',f=>f.r.repository='https://evil.test','REQUEST_SHAPE'],
 ['credential supplied by request',f=>f.r.token='not-a-real-secret','REQUEST_SHAPE'],
 ['parameters inject shell',f=>f.c.parameters={command:'curl evil'},'EXECUTABLE'],
 ['unknown worker',f=>f.c.worker='shell','UNSUPPORTED'],
 ['untrusted mailbox',f=>f.m.mailbox.base='appOTHER','MAILBOX'],
 ['manifest duplicate contract',f=>f.m.contracts.push(clone(f.c)),'CONTRACT_AMBIGUITY'],
 ['wrong approver',f=>f.c.authorization.approved_by='Chief','AUTHORIZATION_MISMATCH']
])test(name+' is rejected before writes',async()=>{const f=fixture();mutate(f);await reject(()=>b.submit(f.m,f.r,f.db,NOW),code);assert.equal(f.db.writes,0);assert.equal(f.gh.workers,0);});
for(const gate of ['production_write','deploy','merge','branch_pr','paid_services'])test(gate+' escalation rejected',async()=>{const f=fixture();f.c.authority[gate]=true;await reject(()=>b.submit(f.m,f.r,f.db,NOW),'AUTHORITY_EXPANSION');assert.equal(f.db.writes,0);});
test('duplicate ID across all rows blocks before any claim',async()=>{const f=fixture();await b.submit(f.m,f.r,f.db,NOW);f.db.rows.push({...clone(f.db.rows[0]),id:'rec99999999999999'});const w=f.db.writes;await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'DUPLICATE_WORK_ORDER');assert.equal(f.db.writes,w);assert.equal(f.gh.workers,0);});
test('concurrent submissions detect duplicate staging and never execute',async()=>{const f=fixture();let release;const barrier=new Promise(r=>release=r),original=f.db.create.bind(f.db);f.db.create=async fields=>{const row=await original(fields);if(f.db.rows.length===2)release();await barrier;return row;};const r=await Promise.allSettled([b.submit(f.m,f.r,f.db,NOW),b.submit(f.m,f.r,f.db,NOW)]);assert.equal(r.filter(x=>x.status==='rejected').length,2);assert.ok(f.db.rows.every(row=>b.get(f.m,row,'status')==='AWAITING_APPROVAL'));await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'DUPLICATE_WORK_ORDER');assert.equal(f.gh.workers,0);});
test('unsupported namespaced row blocks batch before a supported row is claimed',async()=>{const f=fixture();await b.submit(f.m,f.r,f.db,NOW);await f.db.create(b.fields(f.m,{id:'AIR-BRIDGE-OTHER',status:'READY',payload:'{}'}));const writes=f.db.writes;await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'REQUEST_SHAPE');assert.equal(f.db.writes,writes);});
test('historical completed records are byte-identical after execution',async()=>{const f=fixture();f.db.rows.push({id:'rec88888888888888',fields:b.fields(f.m,{id:'AIR-SENTINEL-001',status:'COMPLETE',receipt:'historical'})});const old=clone(f.db.rows[0]);await done(f);assert.deepEqual(f.db.rows[0],old);});
test('foreign claim rejected',async()=>{const f=fixture(),s=await b.submit(f.m,f.r,f.db,NOW);await f.db.patch(s.record,b.fields(f.m,{status:'CLAIMED',attempt:f.c.attempt_id,claimed:'other'}));await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'FOREIGN_CLAIM');});
test('mutated READY envelope fails closed',async()=>{const f=fixture(),s=await b.submit(f.m,f.r,f.db,NOW);const r=clone(f.r);r.contract_digest='b'.repeat(64);await f.db.patch(s.record,b.fields(f.m,{payload:JSON.stringify(r)}));await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'UNSUPPORTED');});
test('live source drift blocks before CLAIMED',async()=>{const f=fixture();await b.submit(f.m,f.r,f.db,NOW);f.gh.preflight=async()=>{throw Error('BASE_SOURCE_DRIFT');};const writes=f.db.writes;await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'BASE_SOURCE_DRIFT');assert.equal(f.db.writes,writes);});
test('interrupted claim after durable write resumes same attempt',async()=>{const f=fixture();await b.submit(f.m,f.r,f.db,NOW);f.db.failAfter=fields=>fields[f.m.mailbox.fields.status]==='CLAIMED';await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'INJECTED_AFTER_WRITE');const resumed=await b.consume(f.m,f.db,f.gh,NOW,'12346');assert.equal(resumed.checkpoint.identity.attempt_id,f.c.attempt_id);assert.equal(f.gh.workers,1);});
test('interrupted checkpoint after durable write reuses output, no worker rerun',async()=>{const f=fixture();await b.submit(f.m,f.r,f.db,NOW);f.db.failAfter=fields=>!!fields[f.m.mailbox.fields.receipt];await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'INJECTED_AFTER_WRITE');const resumed=await b.consume(f.m,f.db,f.gh,NOW,'12346');assert.equal(resumed.checkpoint.worker_run_id,'12345');assert.equal(f.gh.workers,1);});
test('interrupted checkpoint before persistence repeats only a read-only worker',async()=>{const f=fixture();await b.submit(f.m,f.r,f.db,NOW);f.db.failBefore=fields=>!!fields[f.m.mailbox.fields.receipt];await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'INJECTED_BEFORE_WRITE');const resumed=await b.consume(f.m,f.db,f.gh,NOW,'12346');assert.equal(resumed.checkpoint.identity.attempt_id,f.c.attempt_id);assert.equal(f.gh.workers,2);});
test('interrupted terminal status write finalizes receipt without rebuilding',async()=>{const f=fixture(),s=await built(f);f.db.failBefore=fields=>fields[f.m.mailbox.fields.status]==='COMPLETE';await reject(()=>b.complete(f.m,s.record,artifact,f.db,f.gh,NOW),'INJECTED_BEFORE_WRITE');assert.equal(b.rowDecision(f.m,await f.db.read(s.record),NOW).decision,'FINALIZE');await b.consume(f.m,f.db,f.gh,NOW,'12346');assert.equal(f.gh.workers,1);assert.equal(b.get(f.m,await f.db.read(s.record),'status'),'COMPLETE');});
test('terminal replay ignores mutable progress, expired approval, obsolete preflight',async()=>{const f=fixture(),s=await done(f);await f.db.patch(s.record,b.fields(f.m,{next:'Human accepted; mutable progress changed.'}));f.gh.preflight=async()=>{throw Error('OBSOLETE_SOURCE');};const w=f.db.writes;assert.deepEqual(await b.consume(f.m,f.db,f.gh,Date.parse('2026-10-09T00:00:00Z'),'12346'),{decision:'REPLAY'});assert.equal(f.db.writes,w);assert.equal(f.gh.workers,1);});
test('terminal resubmission is replay and does not reset status or attempt',async()=>{const f=fixture(),s=await done(f),w=f.db.writes;assert.equal((await b.submit(f.m,f.r,f.db,NOW)).decision,'REPLAY');assert.equal(f.db.writes,w);assert.equal(b.get(f.m,await f.db.read(s.record),'attempt'),f.c.attempt_id);});
test('conflicting resubmission blocked',async()=>{const f=fixture();await b.submit(f.m,f.r,f.db,NOW);const changed={...f.r,created_at:'2026-10-07T15:31:00Z'};await reject(()=>b.submit(f.m,changed,f.db,NOW),'DUPLICATE_REQUEST_CONFLICT');});
test('mismatched terminal receipt fails closed',async()=>{const f=fixture(),s=await done(f);const row=f.db.rows.find(r=>r.id===s.record),receipt=JSON.parse(b.get(f.m,row,'receipt'));receipt.identity.attempt_id='foreign';row.fields[f.m.mailbox.fields.receipt]=JSON.stringify(receipt);await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12346'),'TERMINAL_IDENTITY');});
test('corrupted checkpoint digest rejected without rerun',async()=>{const f=fixture(),s=await built(f);const row=f.db.rows.find(r=>r.id===s.record),cp=JSON.parse(b.get(f.m,row,'receipt'));cp.output_digest='f'.repeat(64);row.fields[f.m.mailbox.fields.receipt]=JSON.stringify(cp);await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12346'),'CHECKPOINT_DIGEST');assert.equal(f.gh.workers,1);});
test('artifact mismatch prevents completion',async()=>{const f=fixture(),s=await built(f);f.gh.artifactValid=false;await reject(()=>b.complete(f.m,s.record,artifact,f.db,f.gh,NOW),'ARTIFACT_PROVENANCE');assert.equal(b.get(f.m,await f.db.read(s.record),'status'),'CLAIMED');});
test('independent retrieval requires successful run',async()=>{const f=fixture(),s=await done(f);f.gh.successful=false;await reject(()=>b.retrieve(f.m,s.record,f.r,f.db,f.gh,NOW),'RUN_NOT_SUCCESSFUL');});
test('independent retrieval rejects wrong requested correlation',async()=>{const f=fixture(),s=await done(f);await reject(()=>b.retrieve(f.m,s.record,{...f.r,correlation_id:'wrong'},f.db,f.gh,NOW),'CORRELATION');});
test('independent retrieval rejects altered source evidence',async()=>{const f=fixture(),s=await done(f);f.gh.checkpoint=async()=>({bad:true});await reject(()=>b.retrieve(f.m,s.record,f.r,f.db,f.gh,NOW),'INDEPENDENT_SOURCE');});
test('staging readback corruption never publishes READY',async()=>{const f=fixture(),read=f.db.read.bind(f.db);f.db.read=async id=>{const r=await read(id);r.fields[f.m.mailbox.fields.task]='corrupt';return r;};await reject(()=>b.submit(f.m,f.r,f.db,NOW),'STAGING_READBACK');assert.equal(b.get(f.m,f.db.rows[0],'status'),'AWAITING_APPROVAL');});
test('Airtable runtime list paginates; HTTP errors and redirects fail closed',async()=>{const original=global.fetch;let n=0;try{global.fetch=async (url,options)=>{assert.equal(options.redirect,'error');n++;return {ok:true,json:async()=>n===1?{records:[{id:'first'}],offset:'opaque'}:{records:[{id:'second'}]}};};assert.equal((await b.airtableClient(source,'fake').list()).length,2);global.fetch=async()=>({ok:false,status:403});await reject(()=>b.airtableClient(source,'fake').list(),'AIRTABLE_HTTP_403');}finally{global.fetch=original;}});
test('GitHub runtime artifact provenance and success checks',async()=>{const original=global.fetch,receipt={...artifact};try{global.fetch=async url=>({ok:true,json:async()=>url.includes('/actions/runs/')?{repository:{full_name:b.REPO},head_branch:'main',path:'.github/workflows/chief-factory-dispatch-v01.yml',event:'workflow_dispatch',status:'completed',conclusion:'success'}:{expired:false,name:'chief-factory-bridge-evidence',workflow_run:{id:12345},digest:'sha256:'+artifact.artifact_digest}});await b.githubClient('fake').verifyArtifact(receipt,true);receipt.artifact_digest='b'.repeat(64);await reject(()=>b.githubClient('fake').verifyArtifact(receipt,true),'ARTIFACT_PROVENANCE');}finally{global.fetch=original;}});
test('workflow consumer gate cannot run on PRs, has no live scheduling yet',()=>{const w=fs.readFileSync(path.join(__dirname,'../workflows/chief-factory-dispatch-v01.yml'),'utf8');assert.match(w,/workflow_dispatch:/);assert.doesNotMatch(w,/^\s+schedule:/m);assert.match(w,/github.ref == 'refs\/heads\/main'/);assert.match(w,/github.event_name == 'workflow_dispatch'/);assert.match(w,/cancel-in-progress: false/);assert.doesNotMatch(w,/contents: write|pull-requests: write|FACTORY_CROSS_REPO_TOKEN|VERCEL_TOKEN/);});
test('terminal resubmission after authorization expiry returns existing receipt state',async()=>{const f=fixture();await done(f);const w=f.db.writes;assert.equal((await b.submit(f.m,f.r,f.db,Date.parse('2026-10-09T00:00:00Z'))).decision,'REPLAY');assert.equal(f.db.writes,w);});
test('duplicate injected after claim is caught before worker',async()=>{const f=fixture();await b.submit(f.m,f.r,f.db,NOW);const patch=f.db.patch.bind(f.db);f.db.patch=async(id,fields)=>{const r=await patch(id,fields);if(fields[f.m.mailbox.fields.status]==='CLAIMED')f.db.rows.push({...clone(r),id:'rec99999999999999'});return r;};await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'DUPLICATE_WORK_ORDER');assert.equal(f.gh.workers,0);});
test('corrupt claim readback is rejected before worker',async()=>{const f=fixture();await b.submit(f.m,f.r,f.db,NOW);const patch=f.db.patch.bind(f.db);f.db.patch=async(id,fields)=>{const r=await patch(id,fields);if(fields[f.m.mailbox.fields.status]==='CLAIMED')f.db.rows[0].fields[f.m.mailbox.fields.attempt]='foreign';return r;};await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'FOREIGN_CLAIM');assert.equal(f.gh.workers,0);});
test('receipt-write failure before persistence retains reusable checkpoint',async()=>{const f=fixture(),s=await built(f);f.db.failBefore=fields=>!!fields[f.m.mailbox.fields.receipt];await reject(()=>b.complete(f.m,s.record,artifact,f.db,f.gh,NOW),'INJECTED_BEFORE_WRITE');const result=await b.consume(f.m,f.db,f.gh,NOW,'12346');assert.equal(result.checkpoint.worker_run_id,'12345');assert.equal(f.gh.workers,1);});
test('receipt-write failure after persistence retains valid pending terminal checkpoint',async()=>{const f=fixture(),s=await built(f);f.db.failAfter=fields=>!!fields[f.m.mailbox.fields.receipt];await reject(()=>b.complete(f.m,s.record,artifact,f.db,f.gh,NOW),'INJECTED_AFTER_WRITE');await b.consume(f.m,f.db,f.gh,NOW,'12346');assert.equal(f.gh.workers,1);assert.equal(b.get(f.m,await f.db.read(s.record),'status'),'COMPLETE');});
test('successful status write with lost response yields terminal replay',async()=>{const f=fixture(),s=await built(f);f.db.failAfter=fields=>fields[f.m.mailbox.fields.status]==='COMPLETE';await reject(()=>b.complete(f.m,s.record,artifact,f.db,f.gh,NOW),'INJECTED_AFTER_WRITE');assert.deepEqual(await b.consume(f.m,f.db,f.gh,NOW,'12346'),{decision:'REPLAY'});assert.equal(f.gh.workers,1);});
test('completion with duplicate mailbox identity blocks before terminal write',async()=>{const f=fixture(),s=await built(f);f.db.rows.push({...clone(f.db.rows[0]),id:'rec99999999999999'});const w=f.db.writes;await reject(()=>b.complete(f.m,s.record,artifact,f.db,f.gh,NOW),'DUPLICATE_WORK_ORDER');assert.equal(f.db.writes,w);});
test('expiry before resumed execution blocks without changing attempt',async()=>{const f=fixture(),s=await b.submit(f.m,f.r,f.db,NOW);await f.db.patch(s.record,b.fields(f.m,{status:'CLAIMED',attempt:f.c.attempt_id,claimed:b.OWNER}));await reject(()=>b.consume(f.m,f.db,f.gh,Date.parse('2026-10-09T00:00:00Z'),'12346'),'STALE_AUTHORIZATION');assert.equal(f.gh.workers,0);assert.equal(b.get(f.m,await f.db.read(s.record),'attempt'),f.c.attempt_id);});
test('malformed payload and orphan result block before worker',async()=>{const f=fixture(),s=await b.submit(f.m,f.r,f.db,NOW);await f.db.patch(s.record,b.fields(f.m,{payload:'{'}));await reject(()=>b.consume(f.m,f.db,f.gh,NOW,'12345'),'MALFORMED_PAYLOAD');assert.equal(f.gh.workers,0);});
test('raw source mismatch is rejected by bounded worker output',()=>{const f=fixture();assert.throws(()=>b.evidence(f.c,'b'.repeat(40),f.c.target.source_blobs),/SOURCE_DRIFT/);});
